-- Hospital Management System
-- MySQL script. Running this script resets these three tables and their sample data.

CREATE DATABASE IF NOT EXISTS Hospital_Management_System;
USE Hospital_Management_System;

-- Drop child table before parent table so the script can be run again.
DROP TABLE IF EXISTS Patient;
DROP TABLE IF EXISTS Doctor;
DROP TABLE IF EXISTS Department;

CREATE TABLE Department (
    Department_id INT PRIMARY KEY AUTO_INCREMENT,
    Department_name VARCHAR(100) NOT NULL,
    Department_head VARCHAR(100),
    Location VARCHAR(100),
    Contact_number VARCHAR(15)
);

CREATE TABLE Doctor (
    Doctor_id INT PRIMARY KEY AUTO_INCREMENT,
    Doctor_name VARCHAR(100) NOT NULL,
    Specialization VARCHAR(100),
    Phone_number VARCHAR(15),
    Department_id INT NOT NULL,
    CONSTRAINT fk_doctor_department
        FOREIGN KEY (Department_id)
        REFERENCES Department(Department_id)
        ON UPDATE CASCADE
        ON DELETE RESTRICT
);

CREATE TABLE Patient (
    Patient_id INT PRIMARY KEY AUTO_INCREMENT,
    Patient_name VARCHAR(100) NOT NULL,
    Gender VARCHAR(10),
    Age INT,
    Phone VARCHAR(15),
    CONSTRAINT chk_patient_age CHECK (Age IS NULL OR Age BETWEEN 0 AND 120)
);

